sp_widget.client_script:
api.controller = function($scope, $window) {

  var c = this;


  /* =========================================================
     STATE
     ========================================================= */

  c.sidebarCollapsed = false;

  c.loading = false;

  c.topbarSearch = "";

  c.showNotifications = false;

  c.notificationCount = 0;

  c.activeTab = "recruiter";

  c.showRecruiterModal = false;

  c.showMockModal = false;

  c.selectedRecruiter = null;

  c.selectedMock = null;

  c.filteredRecruiterInterviews = [];

  c.filteredMockInterviews = [];


  /* =========================================================
     FILTERS
     ========================================================= */

  c.recruiterFilters = {

    search: "",
    company: "",
    opportunity: "",
    round: "",
    status: "",
    mode: "",
    result: ""

  };


  c.mockFilters = {

    search: "",
    studentId: "",
    trainer: "",
    type: "",
    attendance: "",
    status: ""

  };


  /* =========================================================
     NAVIGATION
     ========================================================= */

  c.goTo = function(pageId) {

    if (!pageId) {
      return;
    }

    try {

      $window.location.href =
        "?id=" + encodeURIComponent(pageId);

    } catch (e) {

      return;

    }

  };


  /* =========================================================
     SIDEBAR
     ========================================================= */

  c.toggleSidebar = function() {

    c.sidebarCollapsed =
      !c.sidebarCollapsed;

  };


  /* =========================================================
     TOPBAR SEARCH
     ========================================================= */

  c.applyTopbarSearch = function() {

    var value =
      c.topbarSearch || "";


    c.recruiterFilters.search =
      value;

    c.mockFilters.search =
      value;


    c.applyRecruiterFilters();

    c.applyMockFilters();

  };


  /* =========================================================
     NOTIFICATIONS
     ========================================================= */

  c.toggleNotifications = function(event) {

    if (event) {

      event.preventDefault();

      event.stopPropagation();

    }


    c.showNotifications =
      !c.showNotifications;

  };


  /* =========================================================
     TAB
     ========================================================= */

  c.setTab = function(tab) {

    if (
      tab !== "recruiter" &&
      tab !== "mock"
    ) {

      return;

    }


    c.activeTab = tab;


    if (tab === "recruiter") {

      c.applyRecruiterFilters();

    } else {

      c.applyMockFilters();

    }

  };


  /* =========================================================
     HELPERS
     ========================================================= */

  function normalize(value) {

    if (
      value === null ||
      value === undefined
    ) {

      return "";

    }

    return String(value)
      .toLowerCase()
      .trim();

  }


  function contains(
    haystack,
    needle
  ) {

    return normalize(haystack)
      .indexOf(
        normalize(needle)
      ) !== -1;

  }


  /* =========================================================
     INITIALS
     ========================================================= */

  c.getInitials = function(name) {

    if (!name) {

      return "ST";

    }


    var parts =
      String(name)
        .trim()
        .split(/\s+/);


    if (parts.length === 1) {

      return parts[0]
        .substring(0, 2)
        .toUpperCase();

    }


    return (
      parts[0].charAt(0) +
      parts[parts.length - 1].charAt(0)
    ).toUpperCase();

  };


  /* =========================================================
     RECRUITER FILTERS
     ========================================================= */

  c.applyRecruiterFilters = function() {

    var filters =
      c.recruiterFilters;


    var source =
      (
        c.data &&
        c.data.recruiterInterviews
      )
      ?
      c.data.recruiterInterviews
      :
      [];


    c.filteredRecruiterInterviews =
      source.filter(function(item) {


        if (
          filters.search &&
          !(
            contains(
              item.interview_id,
              filters.search
            ) ||

            contains(
              item.interviewId,
              filters.search
            ) ||

            contains(
              item.student_name,
              filters.search
            ) ||

            contains(
              item.studentName,
              filters.search
            ) ||

            contains(
              item.student_id,
              filters.search
            ) ||

            contains(
              item.company_name,
              filters.search
            ) ||

            contains(
              item.company,
              filters.search
            ) ||

            contains(
              item.opportunity_name,
              filters.search
            ) ||

            contains(
              item.opportunityTitle,
              filters.search
            ) ||

            contains(
              item.interviewer,
              filters.search
            )
          )
        ) {

          return false;

        }


        if (
          filters.company &&
          item.company_sys_id !==
          filters.company
        ) {

          return false;

        }


        if (
          filters.opportunity &&
          item.opportunity_sys_id !==
          filters.opportunity
        ) {

          return false;

        }


        if (
          filters.round &&
          normalize(
            item.interview_round
          ) !==
          normalize(
            filters.round
          )
        ) {

          return false;

        }


        if (
          filters.status &&
          normalize(item.status) !==
          normalize(filters.status)
        ) {

          return false;

        }


        if (
          filters.mode &&
          normalize(
            item.interview_mode
          ) !==
          normalize(filters.mode)
        ) {

          return false;

        }


        if (
          filters.result &&
          normalize(item.result) !==
          normalize(filters.result)
        ) {

          return false;

        }


        return true;

      });

  };


  /* =========================================================
     CLEAR RECRUITER FILTERS
     ========================================================= */

  c.clearRecruiterFilters =
    function() {

      c.recruiterFilters = {

        search: "",
        company: "",
        opportunity: "",
        round: "",
        status: "",
        mode: "",
        result: ""

      };


      c.applyRecruiterFilters();

    };


  /* =========================================================
     MOCK FILTERS
     ========================================================= */

  c.applyMockFilters = function() {

    var filters =
      c.mockFilters;


    var source =
      (
        c.data &&
        c.data.mockInterviews
      )
      ?
      c.data.mockInterviews
      :
      [];


    c.filteredMockInterviews =
      source.filter(function(item) {


        if (
          filters.search &&
          !(
            contains(
              item.interview_id,
              filters.search
            ) ||

            contains(
              item.interviewId,
              filters.search
            ) ||

            contains(
              item.student_name,
              filters.search
            ) ||

            contains(
              item.studentName,
              filters.search
            ) ||

            contains(
              item.student_id,
              filters.search
            ) ||

            contains(
              item.trainer_name,
              filters.search
            ) ||

            contains(
              item.trainerName,
              filters.search
            ) ||

            contains(
              item.interview_type,
              filters.search
            )
          )
        ) {

          return false;

        }


        if (
          filters.studentId &&
          !contains(
            item.student_id,
            filters.studentId
          )
        ) {

          return false;

        }


        if (
          filters.trainer &&
          item.trainer_sys_id !==
          filters.trainer
        ) {

          return false;

        }


        if (
          filters.type &&
          normalize(
            item.interview_type
          ) !==
          normalize(
            filters.type
          )
        ) {

          return false;

        }


        if (
          filters.attendance &&
          normalize(
            item.attendance_status
          ) !==
          normalize(
            filters.attendance
          )
        ) {

          return false;

        }


        if (
          filters.status &&
          normalize(
            item.interview_status
          ) !==
          normalize(
            filters.status
          )
        ) {

          return false;

        }


        return true;

      });

  };


  /* =========================================================
     CLEAR MOCK FILTERS
     ========================================================= */

  c.clearMockFilters =
    function() {

      c.mockFilters = {

        search: "",
        studentId: "",
        trainer: "",
        type: "",
        attendance: "",
        status: ""

      };


      c.applyMockFilters();

    };


  /* =========================================================
     STATUS CLASS
     ========================================================= */

  c.getStatusClass = function(value) {

    var v =
      normalize(value);


    if (
      v.indexOf("scheduled") !== -1 ||
      v.indexOf("pending") !== -1
    ) {

      return "status-scheduled";

    }


    if (
      v.indexOf("completed") !== -1 ||
      v.indexOf("present") !== -1 ||
      v.indexOf("passed") !== -1
    ) {

      return "status-completed";

    }


    if (
      v.indexOf("cancel") !== -1 ||
      v.indexOf("absent") !== -1 ||
      v.indexOf("failed") !== -1 ||
      v.indexOf("rejected") !== -1
    ) {

      return "status-cancelled";

    }


    return "";

  };


  /* =========================================================
     RESULT CLASS
     ========================================================= */

  c.getResultClass = function(value) {

    var v =
      normalize(value);


    if (
      v.indexOf("selected") !== -1 ||
      v.indexOf("passed") !== -1 ||
      v.indexOf("recommended") !== -1
    ) {

      return "result-selected";

    }


    if (
      v.indexOf("rejected") !== -1 ||
      v.indexOf("failed") !== -1 ||
      v.indexOf("not selected") !== -1
    ) {

      return "result-rejected";

    }


    return "";

  };


  /* =========================================================
     RECRUITER MODAL
     ========================================================= */

  c.openRecruiterInterview =
    function(item) {

      if (!item) {
        return;
      }


      c.selectedRecruiter =
        item;


      c.showRecruiterModal =
        true;

    };


  c.closeRecruiterInterview =
    function() {

      c.showRecruiterModal =
        false;

      c.selectedRecruiter =
        null;

    };


  /* =========================================================
     MOCK MODAL
     ========================================================= */

  c.openMockInterview =
    function(item) {

      if (!item) {
        return;
      }


      c.selectedMock =
        item;


      c.showMockModal =
        true;

    };


  c.closeMockInterview =
    function() {

      c.showMockModal =
        false;

      c.selectedMock =
        null;

    };


  /* =========================================================
     EVALUATION HELPER
     ========================================================= */

  c.hasRecruiterEvaluation =
    function(item) {

      if (!item) {
        return false;
      }


      return !!(
        item.codingScore ||
        item.technicalScore ||
        item.communicationScore ||
        item.problemSolvingScore ||
        item.confidenceScore ||
        item.overallScore ||
        item.recommendation ||
        item.evaluationStatus ||
        item.evaluationFeedback
      );

    };


  /* =========================================================
     REFRESH
     ========================================================= */

  c.refreshData = function() {

    if (c.loading) {
      return;
    }


    c.loading = true;


    c.server.get({

      action: "refresh"

    }).then(

      function(response) {

        if (
          response &&
          response.data
        ) {

          c.data =
            response.data;

        }


        c.applyRecruiterFilters();

        c.applyMockFilters();


        c.loading = false;

      },

      function() {

        c.loading = false;

      }

    );

  };


  /* =========================================================
     ESCAPE KEY
     ========================================================= */

  var keyHandler =
    function(event) {

      if (
        event.key !== "Escape"
      ) {

        return;

      }


      if (
        c.showNotifications
      ) {

        c.showNotifications =
          false;

        return;

      }


      if (
        c.showRecruiterModal
      ) {

        c.closeRecruiterInterview();

      }


      if (
        c.showMockModal
      ) {

        c.closeMockInterview();

      }

    };


  if (
    $window &&
    $window.addEventListener
  ) {

    $window.addEventListener(
      "keydown",
      keyHandler
    );

  }


  $scope.$on(
    "$destroy",
    function() {

      if (
        $window &&
        $window.removeEventListener
      ) {

        $window.removeEventListener(
          "keydown",
          keyHandler
        );

      }

    }
  );


  /* =========================================================
     INITIAL LOAD
     ========================================================= */

  c.applyRecruiterFilters();

  c.applyMockFilters();

};

sp_widget.css:
/* ============================================================
   CAMPUS360 INTERVIEWS
   FULLSCREEN + REMOVE SERVICENOW PORTAL NAV
   ============================================================ */

html,
body {
  width:100% !important;
  height:100% !important;
  margin:0 !important;
  padding:0 !important;
  overflow:hidden !important;
}


/* ============================================================
   REMOVE SERVICENOW TOP NAV
   ============================================================ */

body:has(.campus360-interviews-app) #sp-header,
body:has(.campus360-interviews-app) .sp-header,
body:has(.campus360-interviews-app) .sp-navbar,
body:has(.campus360-interviews-app) #sp-nav-bar,
body:has(.campus360-interviews-app) .sp-nav-bar,
body:has(.campus360-interviews-app) header#sp-header,
body:has(.campus360-interviews-app) header.sp-header,
body:has(.campus360-interviews-app) header.navbar,
body:has(.campus360-interviews-app) nav.navbar,
body:has(.campus360-interviews-app) .navbar,
body:has(.campus360-interviews-app) .navbar-default,
body:has(.campus360-interviews-app) .navbar-inverse,
body:has(.campus360-interviews-app) .portal-header,
body:has(.campus360-interviews-app) .sp-page-header {
  display:none !important;
  visibility:hidden !important;
  height:0 !important;
  min-height:0 !important;
  max-height:0 !important;
  margin:0 !important;
  padding:0 !important;
  overflow:hidden !important;
}


/* SERVICE NOW CONTENT RESET */

body:has(.campus360-interviews-app) .page,
body:has(.campus360-interviews-app) .container,
body:has(.campus360-interviews-app) .container-fluid,
body:has(.campus360-interviews-app) .row,
body:has(.campus360-interviews-app) [class*="col-"] {
  width:100% !important;
  max-width:none !important;
  margin:0 !important;
  padding:0 !important;
}


/* ============================================================
   APP
   ============================================================ */

.campus360-interviews-app,
.campus360-interviews-app * {
  box-sizing:border-box !important;
}

.campus360-interviews-app {
  position:fixed !important;
  inset:0 !important;
  width:100vw !important;
  height:100vh !important;
  display:flex !important;
  overflow:hidden !important;
  background:#f7f9fc !important;
  color:#172033 !important;
  font-family:"Plus Jakarta Sans",Arial,sans-serif !important;
}


/* ============================================================
   SHELL
   ============================================================ */

.interviews-shell {
  width:100% !important;
  height:100% !important;
  display:flex !important;
  overflow:hidden !important;
}


/* ============================================================
   SIDEBAR
   ============================================================ */

.interviews-sidebar {
  position:fixed !important;
  left:0 !important;
  top:0 !important;
  bottom:0 !important;

  width:235px !important;
  min-width:235px !important;

  padding:0 12px !important;

  display:flex !important;
  flex-direction:column !important;

  background:linear-gradient(
    180deg,
    #111025 0%,
    #100e22 100%
  ) !important;

  color:#fff !important;

  overflow-y:auto !important;
  overflow-x:hidden !important;

  z-index:900 !important;

  transition:
    width .25s ease,
    min-width .25s ease,
    transform .25s ease,
    opacity .25s ease !important;
}

.interviews-sidebar::-webkit-scrollbar {
  width:5px !important;
}

.interviews-sidebar::-webkit-scrollbar-thumb {
  background:rgba(255,255,255,.12) !important;
  border-radius:10px !important;
}


/* BRAND */

.sidebar-brand {
  min-height:82px !important;

  display:flex !important;
  align-items:center !important;

  gap:12px !important;

  padding:17px 9px !important;

  border-bottom:1px solid rgba(255,255,255,.06) !important;
}

.brand-icon {
  width:43px !important;
  height:43px !important;
  min-width:43px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:13px !important;

  background:linear-gradient(
    135deg,
    #8b5cf6,
    #6d28d9
  ) !important;

  color:#fff !important;

  font-size:23px !important;
  font-weight:900 !important;
}

.brand-title {
  color:#fff !important;
  font-size:18px !important;
  font-weight:800 !important;
}

.brand-subtitle {
  margin-top:3px !important;

  color:#b8b2cc !important;

  font-size:9px !important;
  font-weight:800 !important;

  letter-spacing:.7px !important;
}


/* TPO CARD */

.tpo-card {
  margin:15px 4px 9px !important;
  padding:12px !important;

  display:flex !important;
  align-items:center !important;

  gap:10px !important;

  border-radius:13px !important;

  background:rgba(124,58,237,.14) !important;
  border:1px solid rgba(124,58,237,.25) !important;
}

.tpo-avatar {
  width:40px !important;
  height:40px !important;
  min-width:40px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:50% !important;

  background:linear-gradient(
    135deg,
    #8b5cf6,
    #6d28d9
  ) !important;

  color:#fff !important;

  font-size:10px !important;
  font-weight:900 !important;
}

.tpo-name {
  color:#fff !important;
  font-size:12px !important;
  font-weight:800 !important;
}

.tpo-role {
  margin-top:2px !important;
  color:#c4bdd6 !important;
  font-size:9px !important;
}

.tpo-description {
  margin-top:2px !important;
  color:#9892aa !important;
  font-size:8px !important;
}


/* SIDEBAR SECTION */

.sidebar-section-title {
  margin:15px 9px 6px !important;

  color:#9791a9 !important;

  font-size:9px !important;
  font-weight:900 !important;

  letter-spacing:.75px !important;
}


/* NAV ITEM */

.sidebar-nav-item {
  width:100% !important;
  min-height:41px !important;

  margin:2px 0 !important;
  padding:0 10px !important;

  display:flex !important;
  align-items:center !important;

  gap:10px !important;

  border:0 !important;
  border-radius:10px !important;

  background:transparent !important;

  color:#d7d3e2 !important;

  font-size:11px !important;
  font-weight:600 !important;

  text-align:left !important;

  cursor:pointer !important;

  transition:.18s ease !important;
}

.sidebar-nav-item:hover {
  background:rgba(255,255,255,.07) !important;
  color:#fff !important;
}

.sidebar-nav-item.active {
  background:linear-gradient(
    90deg,
    #7c3aed,
    #8338ec
  ) !important;

  color:#fff !important;

  box-shadow:
    0 7px 18px rgba(124,58,237,.22) !important;
}

.sidebar-icon {
  width:20px !important;
  min-width:20px !important;

  text-align:center !important;

  color:#aaa5ba !important;
}

.sidebar-nav-item:hover .sidebar-icon,
.sidebar-nav-item.active .sidebar-icon {
  color:#fff !important;
}

.sidebar-count {
  min-width:23px !important;
  height:20px !important;

  margin-left:auto !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  padding:0 6px !important;

  border-radius:20px !important;

  background:rgba(124,58,237,.32) !important;

  color:#d8b4fe !important;

  font-size:8px !important;
  font-weight:900 !important;
}

.sidebar-count.green {
  background:rgba(16,185,129,.16) !important;
  color:#6ee7b7 !important;
}


/* ============================================================
   MAIN
   ============================================================ */

.interviews-main {
  width:calc(100% - 235px) !important;
  min-width:0 !important;

  margin-left:235px !important;

  height:100vh !important;

  display:flex !important;
  flex-direction:column !important;

  overflow:hidden !important;

  background:#f7f9fc !important;

  transition:
    width .25s ease,
    margin-left .25s ease !important;
}


/* ============================================================
   TOP NAVBAR
   ============================================================ */

.interviews-topbar {
  width:100% !important;
  height:72px !important;
  min-height:72px !important;

  padding:0 24px !important;

  display:flex !important;
  align-items:center !important;

  gap:20px !important;

  background:#fff !important;

  border-bottom:1px solid #e2e8f0 !important;

  box-shadow:
    0 2px 12px rgba(15,23,42,.04) !important;

  position:relative !important;

  z-index:500 !important;
}


/* TOPBAR LEFT */

.topbar-left {
  min-width:245px !important;

  display:flex !important;
  align-items:center !important;

  gap:13px !important;
}

.sidebar-toggle {
  width:40px !important;
  height:40px !important;
  min-width:40px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border:1px solid #dbe2ea !important;
  border-radius:10px !important;

  background:#fff !important;

  color:#475569 !important;

  cursor:pointer !important;
}

.sidebar-toggle:hover {
  border-color:#c4b5fd !important;
  background:#faf7ff !important;
  color:#6d28d9 !important;
}

.topbar-title-block {
  display:flex !important;
  flex-direction:column !important;
  justify-content:center !important;
}

.topbar-eyebrow {
  color:#7c3aed !important;
  font-size:9px !important;
  font-weight:800 !important;
  letter-spacing:.9px !important;
}

.topbar-title {
  margin-top:2px !important;
  color:#172033 !important;
  font-size:16px !important;
  font-weight:800 !important;
  white-space:nowrap !important;
}


/* TOPBAR SEARCH */

.topbar-center {
  flex:1 1 auto !important;
  min-width:220px !important;

  display:flex !important;
  justify-content:center !important;
}

.topbar-search {
  width:min(470px,100%) !important;
  height:40px !important;

  padding:0 13px !important;

  display:flex !important;
  align-items:center !important;

  border:1px solid #dbe2ea !important;
  border-radius:11px !important;

  background:#f8fafc !important;
}

.topbar-search:focus-within {
  border-color:#a78bfa !important;
  background:#fff !important;

  box-shadow:
    0 0 0 3px rgba(124,58,237,.08) !important;
}

.topbar-search > i {
  margin-right:9px !important;
  color:#94a3b8 !important;
  font-size:13px !important;
}

.topbar-search input {
  width:100% !important;
  height:100% !important;
  padding:0 !important;

  border:0 !important;
  outline:0 !important;

  background:transparent !important;
  color:#334155 !important;

  font-size:11px !important;
}

.topbar-search input::placeholder {
  color:#94a3b8 !important;
}


/* TOPBAR RIGHT */

.topbar-right {
  min-width:260px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:flex-end !important;

  gap:9px !important;
}

.topbar-circle-button {
  position:relative !important;

  width:40px !important;
  height:40px !important;
  min-width:40px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border:1px solid #dbe2ea !important;
  border-radius:10px !important;

  background:#fff !important;
  color:#475569 !important;

  cursor:pointer !important;
}

.topbar-circle-button:hover {
  border-color:#c4b5fd !important;
  background:#faf7ff !important;
  color:#6d28d9 !important;
}

.topbar-circle-button:disabled {
  opacity:.55 !important;
  cursor:not-allowed !important;
}


/* NOTIFICATION */

.topbar-notification-wrap {
  position:relative !important;
}

.notification-button {
  z-index:510 !important;
}

.notification-button i {
  font-size:16px !important;
  pointer-events:none !important;
}

.notification-dot {
  position:absolute !important;

  top:-5px !important;
  right:-5px !important;

  min-width:17px !important;
  height:17px !important;

  padding:0 4px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border:2px solid #fff !important;
  border-radius:20px !important;

  background:#e11d48 !important;

  color:#fff !important;

  font-size:8px !important;
  font-weight:900 !important;
}

.topbar-notification-popover {
  position:absolute !important;
  top:50px !important;
  right:0 !important;

  width:290px !important;

  overflow:hidden !important;

  border:1px solid #e2e8f0 !important;
  border-radius:13px !important;

  background:#fff !important;

  box-shadow:
    0 18px 50px rgba(15,23,42,.16) !important;

  z-index:1000 !important;
}

.notification-popover-header {
  height:48px !important;
  padding:0 13px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:space-between !important;

  border-bottom:1px solid #edf2f7 !important;
}

.notification-popover-header strong {
  color:#172033 !important;
  font-size:11px !important;
}

.notification-popover-header span {
  min-width:22px !important;
  height:22px !important;

  padding:0 6px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:20px !important;

  background:#ffe4e6 !important;
  color:#be123c !important;

  font-size:9px !important;
  font-weight:900 !important;
}

.notification-popover-body {
  padding:24px 15px !important;
  text-align:center !important;
}

.notification-popover-body > i {
  display:block !important;
  margin-bottom:9px !important;
  color:#0f766e !important;
  font-size:24px !important;
}

.notification-popover-body strong {
  display:block !important;
  color:#334155 !important;
  font-size:11px !important;
}

.notification-popover-body p {
  margin:5px 0 0 !important;
  color:#94a3b8 !important;
  font-size:9px !important;
}


/* PROFILE */

.topbar-profile {
  display:flex !important;
  align-items:center !important;
  gap:9px !important;
  padding-left:5px !important;
}

.topbar-avatar {
  width:38px !important;
  height:38px !important;
  min-width:38px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:50% !important;

  background:
    linear-gradient(
      135deg,
      #7c3aed,
      #4f46e5
    ) !important;

  color:#fff !important;

  font-size:10px !important;
  font-weight:900 !important;
}

.topbar-profile-name {
  color:#172033 !important;
  font-size:11px !important;
  font-weight:800 !important;
  white-space:nowrap !important;
}

.topbar-profile-role {
  max-width:150px !important;
  margin-top:2px !important;

  overflow:hidden !important;
  text-overflow:ellipsis !important;
  white-space:nowrap !important;

  color:#8994a5 !important;
  font-size:8px !important;
}

.profile-arrow {
  color:#94a3b8 !important;
  font-size:12px !important;
}


/* ============================================================
   CONTENT
   INCREASED BODY TYPOGRAPHY
   ============================================================ */

.interviews-content {
  flex:1 !important;

  min-height:0 !important;

  overflow-y:auto !important;
  overflow-x:hidden !important;

  padding:28px 30px 45px !important;

  /* keeps the page scrollable */
  scrollbar-width:thin !important;
  scrollbar-color:#a8b1c2 #edf1f6 !important;
}

.interviews-content::-webkit-scrollbar {
  width:9px !important;
}

.interviews-content::-webkit-scrollbar-track {
  background:#edf1f6 !important;
}

.interviews-content::-webkit-scrollbar-thumb {
  background:#a8b1c2 !important;
  border-radius:8px !important;
  border:2px solid #edf1f6 !important;
}

.interviews-content::-webkit-scrollbar-thumb:hover {
  background:#8d99ad !important;
}


/* PAGE HEADING */

.page-heading-row {
  display:flex !important;
  align-items:flex-end !important;
  justify-content:space-between !important;

  gap:20px !important;

  margin-bottom:20px !important;
}

.page-eyebrow,
.section-eyebrow {
  color:#0f766e !important;

  font-size:11px !important;
  font-weight:900 !important;

  letter-spacing:.9px !important;
}

.page-heading-row h1 {
  margin:7px 0 6px !important;

  color:#172033 !important;

  font-size:34px !important;
  font-weight:900 !important;

  letter-spacing:-.8px !important;
  line-height:1.12 !important;
}

.page-description {
  margin:0 !important;

  color:#64748b !important;

  font-size:14px !important;
  line-height:1.5 !important;
}

.data-source-badge {
  padding:9px 12px !important;

  border:1px solid #dbeafe !important;
  border-radius:20px !important;

  background:#eff6ff !important;

  color:#2563eb !important;

  font-size:11px !important;
  font-weight:800 !important;
}


/* ============================================================
   TABS
   ============================================================ */

.interview-tabs {
  display:flex !important;
  gap:8px !important;
  margin-bottom:18px !important;

  border-bottom:1px solid #e2e8f0 !important;
}

.interview-tab {
  min-height:46px !important;

  padding:0 17px !important;

  display:flex !important;
  align-items:center !important;

  gap:9px !important;

  border:0 !important;
  border-bottom:3px solid transparent !important;

  background:transparent !important;

  color:#64748b !important;

  font-size:12px !important;
  font-weight:800 !important;

  cursor:pointer !important;
}

.interview-tab.active {
  color:#4f46e5 !important;
  border-bottom-color:#4f46e5 !important;
}

.tab-icon {
  font-size:15px !important;
}

.tab-count {
  min-width:23px !important;
  height:21px !important;

  padding:0 6px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:20px !important;

  background:#eef2ff !important;
  color:#4f46e5 !important;

  font-size:9px !important;
}


/* ============================================================
   KPI
   ============================================================ */

.kpi-grid {
  display:grid !important;

  grid-template-columns:
    repeat(4,minmax(0,1fr)) !important;

  gap:14px !important;

  margin-bottom:19px !important;
}

.kpi-card {
  min-height:122px !important;

  padding:18px !important;

  display:flex !important;
  align-items:center !important;

  gap:14px !important;

  border:1px solid #e2e8f0 !important;
  border-radius:14px !important;

  background:#fff !important;

  box-shadow:
    0 6px 20px rgba(15,23,42,.045) !important;
}

.kpi-icon {
  width:47px !important;
  height:47px !important;

  min-width:47px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:12px !important;

  font-size:18px !important;
}

.kpi-label {
  color:#64748b !important;

  font-size:10px !important;
  font-weight:900 !important;

  letter-spacing:.6px !important;
  line-height:1.25 !important;
}

.kpi-value {
  margin-top:5px !important;

  color:#172033 !important;

  font-size:29px !important;
  font-weight:900 !important;

  line-height:1.1 !important;
}

.kpi-blue {
  border-color:#c7d2fe !important;
  background:#f8faff !important;
}

.kpi-icon.blue {
  background:#e0e7ff !important;
  color:#4f46e5 !important;
}

.kpi-orange {
  border-color:#fde68a !important;
  background:#fffcf4 !important;
}

.kpi-icon.orange {
  background:#fef3c7 !important;
  color:#d97706 !important;
}

.kpi-green {
  border-color:#a7f3d0 !important;
  background:#f4fffa !important;
}

.kpi-icon.green {
  background:#d1fae5 !important;
  color:#059669 !important;
}

.kpi-purple {
  border-color:#ddd6fe !important;
  background:#faf8ff !important;
}

.kpi-icon.purple {
  background:#ede9fe !important;
  color:#7c3aed !important;
}


/* ============================================================
   FILTER CARD
   ============================================================ */

.filter-card {
  margin-bottom:19px !important;

  padding:18px !important;

  border:1px solid #e2e8f0 !important;
  border-radius:14px !important;

  background:#fff !important;
}

.section-heading-row {
  display:flex !important;
  align-items:flex-start !important;
  justify-content:space-between !important;

  gap:20px !important;

  margin-bottom:15px !important;
}

.section-heading-row h2 {
  margin:5px 0 4px !important;

  color:#172033 !important;

  font-size:18px !important;
  font-weight:900 !important;

  line-height:1.2 !important;
}

.section-heading-row p {
  margin:0 !important;

  color:#94a3b8 !important;

  font-size:12px !important;
  line-height:1.45 !important;
}

.clear-filter-button {
  height:36px !important;

  padding:0 12px !important;

  border:1px solid #fecdd3 !important;
  border-radius:8px !important;

  background:#fff1f2 !important;

  color:#be123c !important;

  font-size:11px !important;
  font-weight:800 !important;

  cursor:pointer !important;
}

.filter-grid {
  display:grid !important;

  grid-template-columns:
    repeat(4,minmax(0,1fr)) !important;

  gap:11px !important;
}

.filter-field label {
  display:block !important;

  margin-bottom:6px !important;

  color:#64748b !important;

  font-size:10px !important;
  font-weight:900 !important;
}

.filter-field input,
.filter-field select {
  width:100% !important;

  height:39px !important;

  padding:0 10px !important;

  border:1px solid #dbe2ea !important;
  border-radius:8px !important;

  background:#fff !important;

  color:#334155 !important;

  font-size:12px !important;

  outline:none !important;
}

.filter-field input:focus,
.filter-field select:focus {
  border-color:#a78bfa !important;

  box-shadow:
    0 0 0 3px rgba(124,58,237,.07) !important;
}

.input-with-icon {
  height:39px !important;

  display:flex !important;
  align-items:center !important;

  padding:0 10px !important;

  border:1px solid #dbe2ea !important;
  border-radius:8px !important;

  background:#fff !important;
}

.input-with-icon span {
  margin-right:7px !important;
  color:#94a3b8 !important;
  font-size:13px !important;
}

.input-with-icon input {
  border:0 !important;
  outline:0 !important;

  height:100% !important;

  padding:0 !important;
}


/* ============================================================
   DIRECTORY
   ============================================================ */

.directory-card {
  overflow:hidden !important;

  border:1px solid #e2e8f0 !important;
  border-radius:15px !important;

  background:#fff !important;

  box-shadow:
    0 7px 24px rgba(15,23,42,.045) !important;
}

.directory-heading {
  min-height:86px !important;

  padding:18px 20px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:space-between !important;

  gap:20px !important;

  border-bottom:1px solid #e2e8f0 !important;

  background:
    linear-gradient(
      90deg,
      #f0fdfa,
      #fff
    ) !important;
}

.directory-heading h2 {
  margin:5px 0 !important;

  color:#172033 !important;

  font-size:19px !important;
  font-weight:900 !important;
  line-height:1.2 !important;
}

.directory-heading p {
  margin:0 !important;

  color:#8994a5 !important;

  font-size:12px !important;
  line-height:1.4 !important;
}

.record-count {
  padding:8px 11px !important;

  border-radius:20px !important;

  background:#eef2ff !important;

  color:#4338ca !important;

  font-size:10px !important;
  font-weight:800 !important;
}

.directory-table-wrap {
  width:100% !important;
  overflow:auto !important;
}

.directory-table {
  width:100% !important;
  min-width:1050px !important;
  border-collapse:collapse !important;
}

.directory-table thead {
  background:#f8fafc !important;
}

.directory-table th {
  padding:13px 14px !important;

  border-bottom:1px solid #e2e8f0 !important;

  color:#64748b !important;

  font-size:10px !important;
  font-weight:900 !important;

  text-align:left !important;

  white-space:nowrap !important;
}

.directory-table td {
  padding:14px !important;

  border-bottom:1px solid #eef2f6 !important;

  color:#475569 !important;

  font-size:12px !important;

  line-height:1.45 !important;

  vertical-align:middle !important;
}

.directory-table tbody tr:hover {
  background:#faf7ff !important;
}

.student-cell {
  display:flex !important;
  align-items:center !important;
  gap:9px !important;
}

.student-avatar {
  width:36px !important;
  height:36px !important;

  min-width:36px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:50% !important;

  background:#e0e7ff !important;

  color:#4338ca !important;

  font-size:9px !important;
  font-weight:900 !important;
}

.student-cell strong {
  display:block !important;

  color:#172033 !important;

  font-size:12px !important;
  font-weight:800 !important;
}

.student-cell small {
  display:block !important;

  margin-top:2px !important;

  color:#94a3b8 !important;

  font-size:9px !important;
}

.status-pill,
.result-pill {
  display:inline-flex !important;

  align-items:center !important;

  padding:6px 9px !important;

  border-radius:20px !important;

  font-size:9px !important;
  font-weight:900 !important;

  white-space:nowrap !important;
}

.status-scheduled {
  background:#fef3c7 !important;
  color:#b45309 !important;
}

.status-completed {
  background:#d1fae5 !important;
  color:#047857 !important;
}

.status-cancelled {
  background:#ffe4e6 !important;
  color:#be123c !important;
}

.result-selected {
  background:#d1fae5 !important;
  color:#047857 !important;
}

.result-rejected {
  background:#ffe4e6 !important;
  color:#be123c !important;
}

.view-button {
  height:32px !important;

  padding:0 11px !important;

  border:1px solid #c7d2fe !important;
  border-radius:8px !important;

  background:#eef2ff !important;

  color:#4338ca !important;

  font-size:10px !important;
  font-weight:800 !important;

  cursor:pointer !important;
}

.view-button:hover {
  background:#e0e7ff !important;
}


/* EMPTY */

.empty-state {
  padding:60px 20px !important;
  text-align:center !important;
}

.empty-state > i {
  display:block !important;

  margin-bottom:10px !important;

  color:#94a3b8 !important;

  font-size:30px !important;
}

.empty-state strong {
  display:block !important;

  color:#334155 !important;

  font-size:14px !important;
}

.empty-state p {
  margin:6px 0 0 !important;

  color:#94a3b8 !important;

  font-size:11px !important;
}


/* ============================================================
   MODALS
   ============================================================ */

.modal-backdrop {
  position:fixed !important;

  inset:0 !important;

  z-index:1000000 !important;

  display:flex !important;

  align-items:center !important;
  justify-content:center !important;

  padding:25px !important;

  background:rgba(15,23,42,.60) !important;

  backdrop-filter:blur(4px) !important;
}

.interview-modal {
  width:min(920px,95vw) !important;

  max-height:90vh !important;

  display:flex !important;
  flex-direction:column !important;

  overflow:hidden !important;

  border-radius:17px !important;

  background:#fff !important;

  box-shadow:
    0 30px 90px rgba(0,0,0,.28) !important;
}

.modal-header {
  min-height:74px !important;

  padding:15px 18px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:space-between !important;

  border-bottom:1px solid #e2e8f0 !important;
}

.modal-eyebrow {
  color:#0f766e !important;
  font-size:9px !important;
  font-weight:900 !important;
  letter-spacing:.7px !important;
}

.modal-header h2 {
  margin:4px 0 !important;

  color:#172033 !important;

  font-size:19px !important;
  font-weight:900 !important;
}

.modal-subtitle {
  color:#64748b !important;
  font-size:11px !important;
}

.modal-close {
  width:34px !important;
  height:34px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border:0 !important;
  border-radius:8px !important;

  background:#f8fafc !important;
  color:#64748b !important;

  font-size:19px !important;

  cursor:pointer !important;
}

.modal-close:hover {
  background:#ffe4e6 !important;
  color:#be123c !important;
}

.modal-body {
  flex:1 !important;
  overflow:auto !important;
  padding:20px !important;
}

.detail-section {
  margin-bottom:16px !important;

  padding:16px !important;

  border:1px solid #e2e8f0 !important;

  border-radius:12px !important;

  background:#fff !important;
}

.detail-section-heading {
  display:flex !important;
  align-items:center !important;

  gap:9px !important;

  margin-bottom:13px !important;
}

.detail-section-icon {
  width:35px !important;
  height:35px !important;

  display:flex !important;
  align-items:center !important;
  justify-content:center !important;

  border-radius:9px !important;
}

.detail-section-icon.blue {
  background:#e0e7ff !important;
  color:#4f46e5 !important;
}

.detail-section-icon.purple {
  background:#ede9fe !important;
  color:#7c3aed !important;
}

.detail-section-icon.green {
  background:#d1fae5 !important;
  color:#059669 !important;
}

.detail-section-icon.pink {
  background:#ffe4e6 !important;
  color:#e11d48 !important;
}

.detail-section-heading h3 {
  margin:0 !important;

  color:#334155 !important;

  font-size:13px !important;
  font-weight:900 !important;
}

.detail-section-heading p {
  margin:3px 0 0 !important;

  color:#94a3b8 !important;

  font-size:9px !important;
}

.detail-grid {
  display:grid !important;

  grid-template-columns:
    repeat(3,minmax(0,1fr)) !important;

  gap:11px !important;
}

.detail-item {
  min-width:0 !important;
}

.detail-item span {
  display:block !important;

  margin-bottom:4px !important;

  color:#94a3b8 !important;

  font-size:8px !important;
  font-weight:900 !important;

  text-transform:uppercase !important;
}

.detail-item strong {
  color:#334155 !important;

  font-size:11px !important;
  font-weight:700 !important;

  word-break:break-word !important;
}

.full-width-detail {
  grid-column:1 / -1 !important;
}

.meeting-link {
  color:#4f46e5 !important;

  font-weight:800 !important;

  text-decoration:none !important;
}

.meeting-link:hover {
  text-decoration:underline !important;
}

.evaluation-score-grid {
  display:grid !important;

  grid-template-columns:
    repeat(4,minmax(0,1fr)) !important;

  gap:9px !important;
}

.score-card {
  padding:11px !important;

  border:1px solid #e2e8f0 !important;

  border-radius:9px !important;

  background:#f8fafc !important;
}

.score-card span {
  display:block !important;

  color:#94a3b8 !important;

  font-size:8px !important;
  font-weight:900 !important;
}

.score-card strong {
  display:block !important;

  margin-top:4px !important;

  color:#334155 !important;

  font-size:15px !important;
  font-weight:900 !important;
}

.overall-score {
  background:#eef2ff !important;
  border-color:#c7d2fe !important;
}

.overall-score strong {
  color:#4f46e5 !important;
}

.long-text-card {
  margin-top:10px !important;

  padding:12px !important;

  border:1px solid #e2e8f0 !important;

  border-radius:9px !important;

  background:#f8fafc !important;
}

.long-text-card > span {
  display:block !important;

  margin-bottom:5px !important;

  color:#94a3b8 !important;

  font-size:8px !important;
  font-weight:900 !important;
}

.long-text-value {
  color:#475569 !important;

  font-size:11px !important;

  line-height:1.65 !important;

  white-space:pre-wrap !important;
}


/* ============================================================
   SIDEBAR COLLAPSED
   ============================================================ */

.campus360-interviews-app.sidebar-collapsed
.interviews-sidebar {
  width:0 !important;
  min-width:0 !important;

  transform:translateX(-100%) !important;

  opacity:0 !important;

  pointer-events:none !important;

  overflow:hidden !important;
}

.campus360-interviews-app.sidebar-collapsed
.interviews-main {
  width:100% !important;
  margin-left:0 !important;
}


/* ============================================================
   RESPONSIVE
   ============================================================ */

@media (max-width:1200px) {

  .kpi-grid {
    grid-template-columns:
      repeat(2,minmax(0,1fr)) !important;
  }

  .filter-grid {
    grid-template-columns:
      repeat(3,minmax(0,1fr)) !important;
  }

  .detail-grid {
    grid-template-columns:
      repeat(2,minmax(0,1fr)) !important;
  }

}


@media (max-width:950px) {

  .topbar-left {
    min-width:210px !important;
  }

  .topbar-right {
    min-width:215px !important;
  }

  .topbar-profile-text {
    display:none !important;
  }

}


@media (max-width:760px) {

  .interviews-sidebar {
    width:0 !important;
    min-width:0 !important;

    transform:translateX(-100%) !important;

    opacity:0 !important;

    pointer-events:none !important;
  }

  .interviews-main {
    width:100% !important;
    margin-left:0 !important;
  }

  .interviews-topbar {
    padding:0 12px !important;
    gap:8px !important;
  }

  .topbar-left {
    min-width:auto !important;
  }

  .topbar-title-block {
    display:none !important;
  }

  .topbar-center {
    min-width:0 !important;
  }

  .topbar-search {
    width:100% !important;
  }

  .topbar-right {
    min-width:auto !important;
  }

  .profile-arrow {
    display:none !important;
  }

  .interviews-content {
    padding:18px 12px 30px !important;
  }

  .page-heading-row {
    flex-direction:column !important;
    align-items:flex-start !important;
  }

  .data-source-badge {
    display:none !important;
  }

  .kpi-grid,
  .filter-grid,
  .detail-grid {
    grid-template-columns:1fr !important;
  }

  .evaluation-score-grid {
    grid-template-columns:
      repeat(2,minmax(0,1fr)) !important;
  }

  .topbar-notification-popover {
    right:-45px !important;
  }

}


@media (max-width:500px) {

  .evaluation-score-grid {
    grid-template-columns:1fr 1fr !important;
  }

  .notification-popover-body {
    padding:18px 10px !important;
  }

}

sp_widget.script:
(function() {

  /* ==========================================================
     TABLES
     ========================================================== */

  var RECRUITER_TABLE =
    resolveTable(
      "x_snc_campus360_recruiter_interview",
      "recruiter_interview"
    );

  var MOCK_TABLE =
    "x_snc_campus360_mock_interview";

  var FEEDBACK_TABLE =
    resolveTable(
      "x_snc_campus360_interview_feedback",
      "interview_feedback"
    );

  var STUDENT_TABLE =
    "x_snc_campus360_student_master";

  var APPLICATION_TABLE =
    "x_snc_campus360_student_application";

  var OPPORTUNITY_TABLE =
    resolveTable(
      "x_snc_campus360_placement_opportunity",
      "placement_opportunity"
    );

  var COMPANY_TABLE =
    resolveTable(
      "x_snc_campus360_company_master",
      "company_master"
    );

  var TRAINER_TABLE =
    "x_snc_campus360_trainer_master";


  /* ==========================================================
     DATA OBJECTS
     ========================================================== */

  data.recruiterInterviews = [];
  data.mockInterviews = [];

  data.companyOptions = [];
  data.opportunityOptions = [];
  data.trainerOptions = [];

  data.recruiterChoices = {
    status: [
      "Scheduled",
      "Completed",
      "Cancelled",
      "Pending Result"
    ],

    mode: [
      "Online",
      "Offline"
    ],

    round: [
      "Technical Round",
      "HR Round"
    ],

    result: [
      "Pending",
      "Selected",
      "Rejected",
      "Next Round"
    ],

    evaluationStatus: [
      "Pending",
      "Evaluated"
    ]
  };


  data.mockChoices = {
    status: [
      "Scheduled",
      "In Progress",
      "Completed",
      "Cancelled",
      "No Show"
    ],

    type: [
      "Technical",
      "HR",
      "Behavioral",
      "Aptitude",
      "Communication",
      "Domain"
    ],

    qrStatus: [
      "Generated",
      "Scanned",
      "Expired",
      "Cancelled"
    ],

    attendance: []
  };


  data.recruiterSummary = {
    total: 0,
    scheduled: 0,
    completed: 0,
    selected: 0
  };


  data.mockSummary = {
    total: 0,
    scheduled: 0,
    completed: 0,
    present: 0
  };


  data.sidebarCounts = {
    students: 0,
    companies: 0,
    opportunities: 0,
    applications: 0,
    outcomes: 0,
    risks: 0
  };


  /* ==========================================================
     HELPERS
     ========================================================== */

  function resolveTable(scopedName, fallbackName) {

    try {

      var scoped =
        new GlideRecord(scopedName);

      if (scoped.isValid()) {
        return scopedName;
      }

    } catch (e1) {
      // Continue to fallback.
    }


    try {

      var fallback =
        new GlideRecord(fallbackName);

      if (fallback.isValid()) {
        return fallbackName;
      }

    } catch (e2) {
      // Return scoped name.
    }


    return scopedName;

  }


  function hasField(gr, field) {

    try {

      return (
        gr &&
        gr.isValidField(field)
      );

    } catch (e) {

      return false;

    }

  }


  function getValue(gr, field) {

    if (!hasField(gr, field)) {
      return "";
    }

    try {

      return gr.getValue(field) || "";

    } catch (e) {

      return "";

    }

  }


  function getDisplay(gr, field) {

    if (!hasField(gr, field)) {
      return "";
    }

    try {

      return gr.getDisplayValue(field) || "";

    } catch (e) {

      return "";

    }

  }


  function getDateDisplay(gr, field) {

    if (!hasField(gr, field)) {
      return "";
    }

    try {

      return gr.getDisplayValue(field) || "";

    } catch (e) {

      return "";

    }

  }


  function firstNonEmpty(gr, fields) {

    for (
      var i = 0;
      i < fields.length;
      i++
    ) {

      var value =
        getValue(
          gr,
          fields[i]
        );

      if (value) {
        return value;
      }

    }

    return "";

  }


  function firstDisplay(gr, fields) {

    for (
      var i = 0;
      i < fields.length;
      i++
    ) {

      var value =
        getDisplay(
          gr,
          fields[i]
        );

      if (value) {
        return value;
      }

    }

    return "";

  }


  function getReferenceInfo(
    gr,
    field,
    table,
    idFields,
    nameFields
  ) {

    var sysId =
      getValue(gr, field);

    var display =
      getDisplay(gr, field);


    var result = {

      sys_id: sysId,

      display: display,

      id: display,

      name: display

    };


    if (!sysId) {
      return result;
    }


    try {

      var ref =
        new GlideRecord(table);


      if (ref.get(sysId)) {

        result.id =
          firstNonEmpty(
            ref,
            idFields
          ) ||
          firstDisplay(
            ref,
            idFields
          ) ||
          display;


        result.name =
          firstNonEmpty(
            ref,
            nameFields
          ) ||
          firstDisplay(
            ref,
            nameFields
          ) ||
          result.id;


        result.display =
          display ||
          result.id;

      }

    } catch (e) {

      // Keep reference display.

    }


    return result;

  }


  function addUnique(
    array,
    value
  ) {

    if (
      value === null ||
      value === undefined
    ) {
      return;
    }


    value =
      String(value).trim();


    if (!value) {
      return;
    }


    for (
      var i = 0;
      i < array.length;
      i++
    ) {

      if (
        String(array[i]).toLowerCase() ===
        value.toLowerCase()
      ) {

        return;

      }

    }


    array.push(value);

  }


  function makeOptions(
    records,
    valueField,
    labelField
  ) {

    var options = [];
    var seen = {};


    for (
      var i = 0;
      i < records.length;
      i++
    ) {

      var value =
        records[i][valueField];

      var label =
        records[i][labelField];


      if (!value) {
        continue;
      }


      var key =
        String(value).toLowerCase();


      if (seen[key]) {
        continue;
      }


      seen[key] = true;


      options.push({

        value: value,

        label:
          label ||
          value

      });

    }


    options.sort(
      function(a, b) {

        return String(a.label)
          .localeCompare(
            String(b.label)
          );

      }
    );


    return options;

  }


  function choiceValues(
    records,
    field
  ) {

    var values = [];


    for (
      var i = 0;
      i < records.length;
      i++
    ) {

      addUnique(
        values,
        records[i][field]
      );

    }


    return values;

  }


  /* ==========================================================
     COMPANY OPTIONS
     SOURCE:
     x_snc_campus360_company_master
     ========================================================== */

  function loadCompanyOptions() {

    var gr =
      new GlideRecord(
        COMPANY_TABLE
      );


    if (!gr.isValid()) {
      return;
    }


    gr.orderBy("company_name");

    gr.query();


    while (gr.next()) {

      var companyId =
        firstNonEmpty(
          gr,
          [
            "company_id"
          ]
        );


      var companyName =
        firstNonEmpty(
          gr,
          [
            "company_name",
            "name"
          ]
        );


      if (!companyId) {

        companyId =
          gr.getUniqueValue();

      }


      if (!companyName) {

        companyName =
          gr.getDisplayValue();

      }


      if (!companyName) {
        continue;
      }


      data.companyOptions.push({

        value: companyId,

        label: companyName

      });

    }

  }


  /* ==========================================================
     OPPORTUNITY OPTIONS
     SOURCE:
     x_snc_campus360_placement_opportunity

     IMPORTANT:
     This is independent from Recruiter Interview rows.
     Therefore Network Engineer remains available.
     ========================================================== */

  function loadOpportunityOptions() {

    var gr =
      new GlideRecord(
        OPPORTUNITY_TABLE
      );


    if (!gr.isValid()) {
      return;
    }


    gr.orderBy("opportunity_title");

    gr.query();


    while (gr.next()) {

      var opportunityId =
        firstNonEmpty(
          gr,
          [
            "opportunity_id"
          ]
        );


      var opportunityTitle =
        firstNonEmpty(
          gr,
          [
            "opportunity_title",
            "title",
            "name"
          ]
        );


      if (!opportunityId) {

        opportunityId =
          gr.getUniqueValue();

      }


      if (!opportunityTitle) {

        opportunityTitle =
          gr.getDisplayValue();

      }


      if (!opportunityTitle) {
        continue;
      }


      data.opportunityOptions.push({

        value:
          gr.getUniqueValue(),

        id:
          opportunityId,

        label:
          opportunityTitle

      });

    }

  }


  /* ==========================================================
     TRAINER OPTIONS
     SOURCE:
     x_snc_campus360_trainer_master
     ========================================================== */

  function loadTrainerOptions() {

    var gr =
      new GlideRecord(
        TRAINER_TABLE
      );


    if (!gr.isValid()) {
      return;
    }


    gr.orderBy("trainer_name");

    gr.query();


    while (gr.next()) {

      var trainerId =
        firstNonEmpty(
          gr,
          [
            "trainer_id"
          ]
        );


      var trainerName =
        firstNonEmpty(
          gr,
          [
            "trainer_name",
            "name"
          ]
        );


      if (!trainerId) {

        trainerId =
          gr.getUniqueValue();

      }


      if (!trainerName) {

        trainerName =
          gr.getDisplayValue();

      }


      if (!trainerName) {
        continue;
      }


      data.trainerOptions.push({

        value:
          gr.getUniqueValue(),

        id:
          trainerId,

        label:
          trainerName

      });

    }

  }


  /* ==========================================================
     RECRUITER INTERVIEWS
     ========================================================== */

  function loadRecruiterInterviews() {

    var gr =
      new GlideRecord(
        RECRUITER_TABLE
      );


    if (!gr.isValid()) {
      return;
    }


    if (
      hasField(
        gr,
        "interview_date"
      )
    ) {

      gr.orderByDesc(
        "interview_date"
      );

    }


    gr.query();


    while (gr.next()) {


      /* APPLICATION */

      var application =
        getReferenceInfo(
          gr,
          "application",
          APPLICATION_TABLE,
          [
            "application_id",
            "number"
          ],
          [
            "application_id",
            "number"
          ]
        );


      /* STUDENT */

      var student =
        getReferenceInfo(
          gr,
          "student",
          STUDENT_TABLE,
          [
            "student_id"
          ],
          [
            "student_name"
          ]
        );


      /* OPPORTUNITY */

      var opportunity =
        getReferenceInfo(
          gr,
          "opportunity",
          OPPORTUNITY_TABLE,
          [
            "opportunity_id"
          ],
          [
            "opportunity_title"
          ]
        );


      /* COMPANY */

      var companyName = "";


      if (
        opportunity.sys_id
      ) {

        try {

          var opportunityRecord =
            new GlideRecord(
              OPPORTUNITY_TABLE
            );


          if (
            opportunityRecord.get(
              opportunity.sys_id
            )
          ) {

            companyName =
              getDisplay(
                opportunityRecord,
                "company"
              );


            if (
              !companyName
            ) {

              var companyRef =
                getReferenceInfo(
                  opportunityRecord,
                  "company",
                  COMPANY_TABLE,
                  [
                    "company_id"
                  ],
                  [
                    "company_name"
                  ]
                );


              companyName =
                companyRef.name ||
                companyRef.display;

            }

          }

        } catch (e) {

          companyName = "";

        }

      }


      if (!companyName) {

        companyName =
          getDisplay(
            gr,
            "company"
          );

      }


      var item = {

        sys_id:
          gr.getUniqueValue(),

        interviewId:
          getValue(
            gr,
            "interview_id"
          ),

        application:
          application.id ||
          application.display,

        applicationSysId:
          application.sys_id,

        student:
          student.id ||
          student.display,

        studentName:
          student.name ||
          student.display,

        studentSysId:
          student.sys_id,

        opportunity:
          opportunity.id ||
          opportunity.display,

        opportunityTitle:
          opportunity.name ||
          opportunity.display,

        opportunitySysId:
          opportunity.sys_id,

        company:
          companyName,

        interviewRound:
          getDisplay(
            gr,
            "interview_round"
          ),

        status:
          getDisplay(
            gr,
            "status"
          ),

        interviewMode:
          getDisplay(
            gr,
            "interview_mode"
          ),

        interviewer:
          getValue(
            gr,
            "interviewer"
          ),

        meetingLink:
          getValue(
            gr,
            "meeting_link"
          ),

        result:
          getDisplay(
            gr,
            "result"
          ),

        interviewDate:
          getValue(
            gr,
            "interview_date"
          ),

        interviewDateDisplay:
          getDateDisplay(
            gr,
            "interview_date"
          ),

        feedback:
          getValue(
            gr,
            "feedback"
          ),

        codingScore:
          getValue(
            gr,
            "coding_score"
          ),

        technicalScore:
          getValue(
            gr,
            "technical_score"
          ),

        problemSolvingScore:
          getValue(
            gr,
            "problem_solving_score"
          ),

        communicationScore:
          getValue(
            gr,
            "communication_score"
          ),

        confidenceScore:
          getValue(
            gr,
            "confidence_score"
          ),

        overallScore:
          getValue(
            gr,
            "overall_score"
          ),

        recommendation:
          getDisplay(
            gr,
            "recommendation"
          ),

        evaluationFeedback:
          getValue(
            gr,
            "evaluation_feedback"
          ),

        evaluationStatus:
          getDisplay(
            gr,
            "evaluation_status"
          )

      };


      data.recruiterInterviews.push(
        item
      );

    }

  }


  /* ==========================================================
     MOCK INTERVIEWS
     ========================================================== */

  function loadMockInterviews() {

    var gr =
      new GlideRecord(
        MOCK_TABLE
      );


    if (!gr.isValid()) {
      return;
    }


    if (
      hasField(
        gr,
        "interview_date"
      )
    ) {

      gr.orderByDesc(
        "interview_date"
      );

    }


    gr.query();


    while (gr.next()) {


      var student =
        getReferenceInfo(
          gr,
          "student",
          STUDENT_TABLE,
          [
            "student_id"
          ],
          [
            "student_name"
          ]
        );


      var trainer =
        getReferenceInfo(
          gr,
          "trainer",
          TRAINER_TABLE,
          [
            "trainer_id"
          ],
          [
            "trainer_name"
          ]
        );


      var item = {

        sys_id:
          gr.getUniqueValue(),

        interviewId:
          getValue(
            gr,
            "interview_id"
          ),

        student:
          student.id ||
          student.display,

        studentName:
          student.name ||
          student.display,

        studentSysId:
          student.sys_id,

        trainer:
          trainer.id ||
          trainer.display,

        trainerName:
          trainer.name ||
          trainer.display,

        trainerSysId:
          trainer.sys_id,

        interviewType:
          getDisplay(
            gr,
            "interview_type"
          ),

        interviewStatus:
          getDisplay(
            gr,
            "interview_status"
          ),

        attendanceStatus:
          getDisplay(
            gr,
            "attendance_status"
          ),

        interviewDate:
          getValue(
            gr,
            "interview_date"
          ),

        interviewDateDisplay:
          getDateDisplay(
            gr,
            "interview_date"
          ),

        startTime:
          getDisplay(
            gr,
            "start_time"
          ),

        endTime:
          getDisplay(
            gr,
            "end_time"
          ),

        qrCode:
          getValue(
            gr,
            "qr_code"
          ),

        qrStatus:
          getDisplay(
            gr,
            "qr_status"
          ),

        qrUrl:
          getValue(
            gr,
            "qr_url"
          ),

        slotRequest:
          getDisplay(
            gr,
            "slot_request"
          ),

        feedback:
          null

      };


      /* ======================================================
         MOCK FEEDBACK
         SOURCE:
         x_snc_campus360_interview_feedback
         ====================================================== */

      if (
        item.sys_id &&
        FEEDBACK_TABLE
      ) {

        try {

          var feedback =
            new GlideRecord(
              FEEDBACK_TABLE
            );


          if (
            feedback.isValid() &&
            hasField(
              feedback,
              "interview"
            )
          ) {

            feedback.addQuery(
              "interview",
              item.sys_id
            );


            if (
              hasField(
                feedback,
                "feedback_date"
              )
            ) {

              feedback.orderByDesc(
                "feedback_date"
              );

            }


            feedback.setLimit(1);

            feedback.query();


            if (feedback.next()) {

              item.feedback = {

                feedbackId:
                  getValue(
                    feedback,
                    "feedback_id"
                  ),

                feedbackDate:
                  getDateDisplay(
                    feedback,
                    "feedback_date"
                  ),

                technicalScore:
                  getValue(
                    feedback,
                    "technical_score"
                  ),

                communicationScore:
                  getValue(
                    feedback,
                    "communication_score"
                  ),

                problemSolvingScore:
                  getValue(
                    feedback,
                    "problem_solving_score"
                  ),

                overallScore:
                  getValue(
                    feedback,
                    "overall_score"
                  ),

                recommendation:
                  getValue(
                    feedback,
                    "recommendation"
                  ),

                strengths:
                  getValue(
                    feedback,
                    "strengths"
                  ),

                improvementAreas:
                  getValue(
                    feedback,
                    "improvement_areas"
                  )

              };

            }

          }

        } catch (e) {

          item.feedback = null;

        }

      }


      data.mockInterviews.push(
        item
      );

    }

  }


  /* ==========================================================
     SUMMARY
     ========================================================== */

  function buildRecruiterSummary() {

    var rows =
      data.recruiterInterviews;


    data.recruiterSummary.total =
      rows.length;


    for (
      var i = 0;
      i < rows.length;
      i++
    ) {

      var status =
        String(
          rows[i].status || ""
        )
        .toLowerCase();


      var result =
        String(
          rows[i].result || ""
        )
        .toLowerCase();


      if (
        status === "scheduled"
      ) {

        data.recruiterSummary.scheduled++;

      }


      if (
        status === "completed"
      ) {

        data.recruiterSummary.completed++;

      }


      if (
        result === "selected"
      ) {

        data.recruiterSummary.selected++;

      }

    }

  }


  function buildMockSummary() {

    var rows =
      data.mockInterviews;


    data.mockSummary.total =
      rows.length;


    for (
      var i = 0;
      i < rows.length;
      i++
    ) {

      var status =
        String(
          rows[i].interviewStatus || ""
        )
        .toLowerCase();


      var attendance =
        String(
          rows[i].attendanceStatus || ""
        )
        .toLowerCase();


      if (
        status === "scheduled"
      ) {

        data.mockSummary.scheduled++;

      }


      if (
        status === "completed"
      ) {

        data.mockSummary.completed++;

      }


      if (
        attendance === "present"
      ) {

        data.mockSummary.present++;

      }

    }

  }


  /* ==========================================================
     CHOICE VALUES

     These are based on the exact values supplied by you.
     ========================================================== */

  function buildChoiceLists() {

    data.recruiterChoices = {

      status: [
        "Scheduled",
        "Completed",
        "Cancelled",
        "Pending Result"
      ],

      mode: [
        "Online",
        "Offline"
      ],

      round: [
        "Technical Round",
        "HR Round"
      ],

      result: [
        "Pending",
        "Selected",
        "Rejected",
        "Next Round"
      ],

      evaluationStatus: [
        "Pending",
        "Evaluated"
      ]

    };


    data.mockChoices = {

      status: [
        "Scheduled",
        "In Progress",
        "Completed",
        "Cancelled",
        "No Show"
      ],

      type: [
        "Technical",
        "HR",
        "Behavioral",
        "Aptitude",
        "Communication",
        "Domain"
      ],

      qrStatus: [
        "Generated",
        "Scanned",
        "Expired",
        "Cancelled"
      ],

      attendance:
        choiceValues(
          data.mockInterviews,
          "attendanceStatus"
        )

    };

  }


  /* ==========================================================
     SIDEBAR COUNTS
     ========================================================== */

  function buildSidebarCounts() {

    try {

      var gr =
        new GlideRecord(
          STUDENT_TABLE
        );

      if (gr.isValid()) {

        gr.query();

        while (gr.next()) {
          data.sidebarCounts.students++;
        }

      }

    } catch (e1) {}


    try {

      var gr2 =
        new GlideRecord(
          COMPANY_TABLE
        );

      if (gr2.isValid()) {

        gr2.query();

        while (gr2.next()) {
          data.sidebarCounts.companies++;
        }

      }

    } catch (e2) {}


    try {

      var gr3 =
        new GlideRecord(
          OPPORTUNITY_TABLE
        );

      if (gr3.isValid()) {

        gr3.query();

        while (gr3.next()) {
          data.sidebarCounts.opportunities++;
        }

      }

    } catch (e3) {}


    try {

      var gr4 =
        new GlideRecord(
          APPLICATION_TABLE
        );

      if (gr4.isValid()) {

        gr4.query();

        while (gr4.next()) {
          data.sidebarCounts.applications++;
        }

      }

    } catch (e4) {}

  }


  /* ==========================================================
     EXECUTION
     ========================================================== */

  loadCompanyOptions();

  loadOpportunityOptions();

  loadTrainerOptions();

  loadRecruiterInterviews();

  loadMockInterviews();

  buildChoiceLists();

